  "inlineSchema": "// Este es el archivo \"schema\" de Prisma.\n// Define la conexión a tu base de datos y la estructura de tus tablas.\n\n// 1. Configuración del \"Generador\"\n// Esto le dice a Prisma que genere el \"Prisma Client\" para TypeScript.\ngenerator client {\n  provider = \"prisma-client-js\"\n}\n\n// 2. Configuración de la \"Fuente de Datos\"\n// Aquí le decimos a Prisma que estamos usando PostgreSQL\n// y que la URL de conexión está en el archivo .env\ndatasource db {\n  provider = \"postgresql\"\n  url      = env(\"DATABASE_URL\") // Carga la variable DATABASE_URL del archivo .env\n}\n\n// 3. Definición de \"Enums\" (Tipos predefinidos)\n\n// Roles de Usuario\nenum Role {\n  USER // Usuario normal (puede comprar y vender)\n  ADMIN // Administrador de la plataforma\n}\n\n// Estados de una Transacción (nuestro flujo de Escrow)\nenum TransactionStatus {\n  INICIADO // La transacción fue creada\n  PAGADO_EN_RETENCION // El comprador pagó, el dinero está retenido\n  COMPLETADO // El comprador confirmó, el dinero se libera al vendedor\n  DISPUTADO // El comprador inició una disputa\n  CANCELADO // La transacción fue cancelada\n}\n\n// 4. Definición de \"Modelos\" (Nuestras tablas de la base de datos)\n\n// Modelo de Usuario\nmodel User {\n  id        String   @id @default(uuid()) // ID único (ej: \"a1b2c3d4-...\")\n  email     String   @unique // El email debe ser único\n  password  String // La contraseña (guardaremos una versión encriptada)\n  name      String? // Nombre (opcional)\n  role      Role     @default(USER) // Por defecto, todos son \"USER\"\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  // --- Relaciones ---\n  products             Product[] // Un usuario puede tener muchos Productos\n  services             Service[] // Un usuario puede tener muchos Servicios\n  transactionsAsBuyer  Transaction[]        @relation(\"BuyerTransactions\") // Transacciones donde es Comprador\n  transactionsAsSeller Transaction[]        @relation(\"SellerTransactions\") // Transacciones donde es Vendedor\n  ratingsGiven         Rating[]             @relation(\"RaterRatings\") // Calificaciones que ha dado\n  ratingsReceived      Rating[]             @relation(\"RatedRatings\") // Calificaciones que ha recibido\n  professionalProfile  ProfessionalProfile? // Un usuario puede tener UN perfil profesional (o ninguno)\n}\n\n// Modelo de Perfil Profesional (asociado a un Usuario)\nmodel ProfessionalProfile {\n  id              String   @id @default(uuid())\n  user            User     @relation(fields: [userId], references: [id])\n  userId          String   @unique // Un perfil por usuario\n  title           String? // Título (ej: \"Electricista Matriculado\")\n  experienceYears Int? // Años de experiencia\n  education       String? // Educación (ej: \"Técnico en...)\n  summary         String?  @db.Text // Resumen largo\n  createdAt       DateTime @default(now())\n  updatedAt       DateTime @updatedAt\n}\n\n// Modelo de Producto\nmodel Product {\n  id          String   @id @default(uuid())\n  creator     User     @relation(fields: [creatorId], references: [id])\n  creatorId   String\n  title       String\n  description String   @db.Text\n  price       Float // Usamos Float para precios (ej: 1500.50)\n  images      String[] // Un array de URLs de imágenes\n  status      String   @default(\"DISPONIBLE\") // ej: DISPONIBLE, VENDIDO\n  createdAt   DateTime @default(now())\n  updatedAt   DateTime @updatedAt\n\n  // --- Relaciones ---\n  transactions Transaction[] // Un producto puede estar en muchas transacciones\n}\n\n// Modelo de Servicio\nmodel Service {\n  id              String   @id @default(uuid())\n  creator         User     @relation(fields: [creatorId], references: [id])\n  creatorId       String\n  title           String\n  description     String   @db.Text\n  price           Float // Precio base del servicio\n  status          String   @default(\"DISPONIBLE\")\n  timesContracted Int      @default(0) // Contador de \"veces contratado\"\n  createdAt       DateTime @default(now())\n  updatedAt       DateTime @updatedAt\n\n  // --- Relaciones ---\n  transactions Transaction[] // Un servicio puede estar en muchas transacciones\n}\n\n// Modelo de Transacción (¡El corazón del Escrow!)\nmodel Transaction {\n  id       String @id @default(uuid())\n  buyer    User   @relation(\"BuyerTransactions\", fields: [buyerId], references: [id])\n  buyerId  String\n  seller   User   @relation(\"SellerTransactions\", fields: [sellerId], references: [id])\n  sellerId String\n\n  // Una transacción puede ser de UN producto O UN servicio (ambos opcionales ?)\n  product   Product? @relation(fields: [productId], references: [id])\n  productId String?\n  service   Service? @relation(fields: [serviceId], references: [id])\n  serviceId String?\n\n  status        TransactionStatus @default(INICIADO) // El estado del Escrow\n  amount        Float // Monto total pagado por el comprador\n  platformFee   Float // Comisión de MossTall\n  sellerPayout  Float // Dinero a liberar al vendedor\n  mercadoPagoId String?           @unique // ID del pago en Mercado Pago\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  // --- Relaciones ---\n  rating Rating? // Una transacción tiene UNA calificación (o ninguna)\n}\n\n// Modelo de Calificación (asociado a una Transacción)\nmodel Rating {\n  id            String      @id @default(uuid())\n  transaction   Transaction @relation(fields: [transactionId], references: [id])\n  transactionId String      @unique // Solo una calificación por transacción\n\n  rater   User   @relation(\"RaterRatings\", fields: [raterId], references: [id]) // Quién califica (Comprador)\n  raterId String\n  rated   User   @relation(\"RatedRatings\", fields: [ratedId], references: [id]) // A quién califican (Vendedor)\n  ratedId String\n\n  rating  Int // Calificación general (ej: 1 a 5)\n  comment String? @db.Text\n\n  // Campos granulares (especialmente para servicios)\n  quality         Int? // Calidad del trabajo\n  professionalism Int? // Profesionalismo\n  communication   Int? // Comunicación\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n}\n",
